"""Ledger parsing and formatting."""

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_FIELD_SPLIT = re.compile(r"[ \t]+")

# Exact arithmetic for amounts of any length (the default context rounds at 28 digits).
EXACT = decimal.Context(prec=10**6)
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A ledger line is invalid. ``line`` is the 1-based physical line number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Parse ``YYYY-MM-DD`` into a date; raise ValueError if malformed or impossible."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date.fromisoformat(text)
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def _parse_line(number, line):
    parts = _FIELD_SPLIT.split(line.strip(), maxsplit=3)
    if len(parts) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_text, category, amount_text = parts[:3]
    note = parts[3].strip() if len(parts) == 4 else ""
    try:
        date = parse_date(date_text)
    except ValueError as exc:
        raise ParseError(number, str(exc)) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(
            number, "invalid amount %r (at most two decimal places)" % amount_text
        )
    return Entry(date, category.lower(), Decimal(amount_text), note)


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    entries = []
    for number, raw in enumerate(text.split("\n"), start=1):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(_parse_line(number, line))
    return entries


def format_amount(amount):
    """Format an amount with exactly two decimals (never ``-0.00``)."""
    q = amount.quantize(_CENT, context=EXACT)
    if q == 0:
        q = Decimal("0.00")
    return f"{q:.2f}"


def format_entry(entry):
    """Canonical ledger line for an entry: ``DATE CATEGORY AMOUNT[ NOTE]``."""
    line = f"{entry.date.isoformat()} {entry.category} {format_amount(entry.amount)}"
    if entry.note:
        line += f" {entry.note}"
    return line

